-- Dedicated mop_test database only. Test identity/data do not assert production approval.
DO $$ BEGIN IF current_database() <> 'mop_test' THEN RAISE EXCEPTION 'MOP test migrations require dedicated mop_test database'; END IF; END $$;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON SCHEMA public FROM mop_test_runtime;
GRANT USAGE ON SCHEMA public TO mop_test_runtime;

CREATE TABLE public.mop_tenant (
  id uuid PRIMARY KEY, name varchar(100) NOT NULL UNIQUE, created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE public.mop_user (
  id uuid PRIMARY KEY, identity_source varchar(64) NOT NULL, subject varchar(255) NOT NULL,
  display_name varchar(100) NOT NULL, role_code varchar(32) NOT NULL CHECK(role_code IN ('padmin','msp','tadmin','viewer')),
  active boolean NOT NULL DEFAULT true, UNIQUE(identity_source,subject)
);
CREATE TABLE public.mop_membership (
  tenant_id uuid NOT NULL REFERENCES public.mop_tenant(id), user_id uuid NOT NULL REFERENCES public.mop_user(id),
  role_code varchar(32) NOT NULL CHECK(role_code IN ('padmin','msp','tadmin','viewer')),
  permission_version bigint NOT NULL DEFAULT 1 CHECK(permission_version>=1), active boolean NOT NULL DEFAULT true,
  PRIMARY KEY(tenant_id,user_id)
);
CREATE INDEX mop_membership_user ON public.mop_membership(user_id,active,tenant_id);
CREATE TABLE public.mop_site (
  tenant_id uuid NOT NULL REFERENCES public.mop_tenant(id), id varchar(64) NOT NULL, name varchar(100) NOT NULL,
  PRIMARY KEY(tenant_id,id)
);
CREATE TABLE public.mop_asset (
  id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES public.mop_tenant(id), name varchar(100) NOT NULL,
  type varchar(32) NOT NULL CHECK(type IN ('router','switch','firewall','ap','wireless_controller','other')),
  management_ip varchar(45) NOT NULL, site_id varchar(64) NOT NULL,
  status varchar(32) NOT NULL DEFAULT 'unknown', lifecycle_status varchar(32) NOT NULL DEFAULT 'DRAFT',
  source varchar(32) NOT NULL, sampled_at timestamptz(3), unknown_reason text,
  version bigint NOT NULL DEFAULT 1 CHECK(version>=1), created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(), created_by uuid REFERENCES public.mop_user(id), updated_by uuid REFERENCES public.mop_user(id),
  availability varchar(32) NOT NULL DEFAULT 'UNKNOWN', sync_state varchar(32) NOT NULL DEFAULT 'PENDING_ONBOARDING',
  UNIQUE(tenant_id,name), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,site_id) REFERENCES public.mop_site(tenant_id,id)
);
CREATE INDEX mop_asset_tenant_order ON public.mop_asset(tenant_id,created_at,id);
CREATE TABLE public.mop_configuration (
  key varchar(128) PRIMARY KEY, registry_json jsonb NOT NULL, draft_json jsonb,
  version bigint NOT NULL DEFAULT 1 CHECK(version>=1), lifecycle_status varchar(32) NOT NULL DEFAULT 'NONE',
  updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE public.mop_idempotency (
  actor_id uuid NOT NULL REFERENCES public.mop_user(id), tenant_id uuid NOT NULL REFERENCES public.mop_tenant(id),
  route varchar(255) NOT NULL, request_key varchar(128) NOT NULL, payload_hash char(64) NOT NULL,
  response_json jsonb NOT NULL, created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY(actor_id,tenant_id,route,request_key)
);
CREATE TABLE public.mop_audit (
  id uuid PRIMARY KEY, namespace varchar(64) NOT NULL, tenant_id uuid REFERENCES public.mop_tenant(id),
  sequence bigint NOT NULL CHECK(sequence>=1), previous_hash char(64) NOT NULL, entry_hash char(64) NOT NULL,
  payload jsonb NOT NULL, created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(), UNIQUE(namespace,sequence),
  CHECK(entry_hash=payload->>'entry_hash'), CHECK(sequence=(payload->>'sequence')::bigint)
);
CREATE INDEX mop_audit_tenant_order ON public.mop_audit(tenant_id,sequence DESC);

SELECT md5('mop-fixture-user-'||seed)::uuid,'test_oidc','http://127.0.0.1:18110/realms/mop-test|'||
 CASE seed WHEN 'padmin' THEN '814da2d2-30fb-474f-a78f-727b3ccff9d5' WHEN 'msp' THEN '64bbc229-8f87-4418-adff-dab86f421e99'
 WHEN 'tadmin' THEN '9d51723e-f151-40c9-8c76-4df3b9168f9f' WHEN 'viewerA' THEN '397d0deb-5915-41ea-8618-cc9527147eca'
 WHEN 'viewerB' THEN 'b95554f5-10a2-41aa-a551-e44fc7394cbe' END,display_name,role_code
FROM (VALUES('padmin','平台管理员（测试身份）','padmin'),('msp','服务工程师（测试身份）','msp'),
 ('tadmin','租户 A 管理员（测试身份）','tadmin'),('viewerA','租户 A 只读用户（测试身份）','viewer'),
 ('viewerB','租户 B 只读用户（测试身份）','viewer')) AS seeds(seed,display_name,role_code);
SELECT t.id,u.id,u.role_code FROM public.mop_tenant t CROSS JOIN public.mop_user u
WHERE u.role_code IN ('padmin','msp') OR
 (t.id='55000000-0000-4000-8000-000000000001' AND u.id IN (md5('mop-fixture-user-tadmin')::uuid,md5('mop-fixture-user-viewerA')::uuid)) OR
 (t.id='55000000-0000-4000-8000-000000000002' AND u.id=md5('mop-fixture-user-viewerB')::uuid);
SELECT md5(t.id::text||'asset'||i)::uuid,t.id,'虚构设备 '||lpad(i::text,2,'0'),
 CASE WHEN i%2=0 THEN 'switch' ELSE 'router' END,
 CASE WHEN t.id='55000000-0000-4000-8000-000000000001' THEN '192.0.2.' ELSE '198.51.100.' END||i,
 CASE WHEN t.id='55000000-0000-4000-8000-000000000001' THEN 'site-a-main' ELSE 'site-b-main' END,
 'test_seed','虚构测试资产，未接入监控，没有采样事实',
 '2026-09-30T00:00:00Z'::timestamptz(3)+i*interval '1 second','2026-09-30T00:00:00Z'::timestamptz(3)+i*interval '1 second'
FROM public.mop_tenant t CROSS JOIN generate_series(1,18) AS i;

-- Runtime cannot migrate, edit the registry, remove replay results, or rewrite/delete audit history.
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM mop_test_runtime;
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM mop_test_runtime;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM mop_test_runtime;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM mop_test_runtime;
GRANT SELECT ON public.mop_tenant,public.mop_user,public.mop_membership,public.mop_site,public.mop_asset,public.mop_configuration,public.mop_idempotency,public.mop_audit TO mop_test_runtime;
GRANT INSERT ON public.mop_asset,public.mop_idempotency,public.mop_audit TO mop_test_runtime;
GRANT UPDATE(active) ON public.mop_user TO mop_test_runtime;
GRANT UPDATE(active,permission_version) ON public.mop_membership TO mop_test_runtime;
GRANT UPDATE(draft_json,version,lifecycle_status,updated_at) ON public.mop_configuration TO mop_test_runtime;

-- Frozen design registry: null values stay null; draft storage never activates them.
